function reportCheckoutButtonClick(params='') {
    var biLogUrl = litb.paymentUrl + 'log_204/signin?'+params+'&get_frame=1&language=en&log_event=checkout_button_click&vela_device=&vela_is_first_visit=&vela_s=&vela_s_c=&vela_v=&vela_v_c=&vela_w=&vela_w_c=';
    $.ajax({
        type: 'get',
        url: biLogUrl,
        dataType: "jsonp",
    });
}

function requestFloatingSign(params) {
    var params=typeof params==="undefined"?{}:params;
    params=Object.assign({
        targetUrl:""
    },params);
    var gwURLHead = litb.gwBaseURL;
    var domainUrl = 'https://gw.lightinthebox.com';
    if (location.href.indexOf("lightinthebox.com") == -1) {
        domainUrl = 'https://www.miniinthebox.com';
    }
    gwURLHead = gwURLHead ? gwURLHead : domainUrl;
    if (gwURLHead && !gwURLHead.endsWith('/')) {
        gwURLHead += '/';
    }
    var _p='';
    if (window.isProceedToCheckout == true) {
        _p += "&is_from_cart=1";
    }
    if(params.targetUrl){
        _p+='&targetUrl='+params.targetUrl;
    }
    if(params.is_from_mini_header){
        _p+='&is_from_mini_header='+params.is_from_mini_header;
    }
    if (window.isProceedToCheckout == true && !window.ignoreLog204) {
        reportCheckoutButtonClick(_p);
    }
    $.ajax({
        type: 'get',
        url: gwURLHead + 'index.php?main_page=login'+_p+'&get_frame=1&language=en',
        success: function(data) {
            data = eval('[' + data + ']')[0];
            $('head').append(data.style);
            $('head').append('<link rel="stylesheet" href="https://litb-cgis.rightinthebox.com/resource_90d2fcd7b9e253ea0d18719bc663c651ea6b38c0_litb//dev_v2/chosen.css" />');
            $.getScript('https://litb-cgis.rightinthebox.com/resource_90d2fcd7b9e253ea0d18719bc663c651ea6b38c0_litb//dev_v2/chosen.jquery.js', function() {$('#area_code').chosen({width: 98});});
            LitbPopupDialog.loginPopup = new HtmlPopup({width:780, html:data.html, closeWhenClickingBg:true});
            LitbPopupDialog.loginPopup.center = function() {
                $('body').addClass('show-popup');
                LitbPopupDialog.loginPopup.winbox.show().css({
                    "top": Math.max(0,  $(window).height() / 2 - LitbPopupDialog.loginPopup.winbox.height() / 2),
                    "left": Math.max(0, $(window).scrollLeft() + $(window).width() / 2 - LitbPopupDialog.loginPopup.winbox.width() / 2)
                })
             };
             eval(data.script);
            LitbPopupDialog.loginPopup.show();
            LitbPopupDialog.loginPopupCallback({
                is_from_mini_header:params.is_from_mini_header
            });

            LitbPopupDialog.dataScript=data.script;
            LitbPopupDialog.loginPopup.layer.bind('click',
                function() {
                    LitbPopupDialog.loginPopup.hide();
                    $('body').removeClass("show-popup");
                }
            );
            $('#lb-close').off().bind('click',
                function() {
                    LitbPopupDialog.loginPopup.hide();
                    $('body').removeClass("show-popup");
                    return false;
                }
            );
        },
        error: function() {
            alert(litb.langs.networkError);
        }
    });
}

function requestCheckoutFloatingSign(signSuccessCb, source) {
    $.ajax({
        type: 'get',
        url: litb.baseURL + 'index.php?main_page=checkout_login&get_frame=1&language=en&src=' + source,
        data: '',
        complete: function() {
        },
        success: function(data) {
            data = eval('[' + data + ']')[0];
            $('head').append(data.style);
            var popup = new HtmlPopup({width:640, html:data.html, closeWhenClickingBg:false}).show();
            $('#loginEmail').focus();
            popup.winbox.css('top', $(window).scrollTop() + 100);

            $('#lb-content').css('overflow', 'visible');
            $('head').append('<link rel="stylesheet" href="https://litb-cgis.rightinthebox.com/resource_90d2fcd7b9e253ea0d18719bc663c651ea6b38c0_litb//dev_v2/chosen.css" />');
            $.getScript('https://litb-cgis.rightinthebox.com/resource_90d2fcd7b9e253ea0d18719bc663c651ea6b38c0_litb//dev_v2/chosen.jquery.js', function() {$('#country').chosen({width: 220});});

            $('#floatingSign .nav-tabs a').click(function (e) {
                e.preventDefault();
                $(this).tab('show');
                var idx = $('#floatingSign .nav-tabs a').index(this);
                $('#floatingSign .tab-content > div:eq('+idx+') input:not([type="hidden"]):first').focus();
            })
            eval(data.script);
            $('#floatingSign').data('callback', signSuccessCb);
        },
        error: function() {
            alert(litb.langs.networkError);
        }
    });
}

$(function() {
	$('.signToRedirect').click( function(e) {
        e.preventDefault();
		var me = $(this);
        requestFloatingSign(
        	function() {jumpToUrl(me.attr('href'));},
        	me.attr('srcname'), encodeURIComponent(me.attr('href'))
        );
        return false;
	});
});
</script>
