       checkMaxMin: function ($container) {
           var max = $container.attr("data-max-quantity");
           var min = Number($container.attr("data-min-quantity")) || 1;
           var $input = $container.find(".quantity-num");
           var $decrease = $container.find(".num_decrease");
           var $increase = $container.find(".num_increase");
           var now = Number($input.val());
           if (now <= min) {
               $input.val(min);
               now = min;
               //    $input.attr('old-value', now);
           } else if (max && now >= Number(max)) {
               if (Number(max) < 0) {
                   $container.attr("data-max-quantity", "");
               } else {
                   $input.val(max);
                   now = Number(max);
               }
           }
           if (now === min) {
               $decrease.addClass("disabled");
           } else {
               $decrease.removeClass("disabled");
           }
           if (max && now === Number(max)) {
               $increase.addClass("disabled");
           } else {
               $increase.removeClass("disabled");
           }
       },
       triggerChange: function ($containers, val) {
           $containers.each(function (i, t) {
               var $input = $(t).find(".quantity-num");
               var now = $input.val();
               if (val != now) {
                   $input.trigger("change");
               }
           });
       }
   };

   function stringifyItem(item) {
       var attrs = '';
       // header优化
       var quantityControlTemplate =
           '<div class="order-quantity attr-model">' +
           '<div class="quantity-select" data-min-quantity="'+ item.min_qty + '"  data-max-quantity="'+ item.max_qty +'" data-checked="'+ (item.checked ? 1 : 0) +'">';

       if (!item.new_free_gift) {
           quantityControlTemplate += '<span class="btn-quantity num_decrease ' + (item.qty <= item.min_qty ? 'disabled' : '') + '" >' +
               '<em class="icon iconfont iconproductoptions_ic_qty-"></em>' +
               '</span>';
       }

       if (!item.new_free_gift) {
           quantityControlTemplate += '<input aria-label="Qty" type="text" name="cart_quantity" data-key="' + item.id + '" data-id="' + item.products_id + '" id="quantity_' + (item.id.indexOf(':') > -1 ? item.id.replace(/:/, '_') : item.id) + '" class="quantity-num ' + '" autocomplete="off" old-value="' + item.qty + '" value="' + item.qty + '"/>';
       } else {
           quantityControlTemplate += '<div style="font-size: 12px;">x ' + item.qty + '</div>';
       }

       if (!item.new_free_gift) {
           quantityControlTemplate += '<span class="btn-quantity num_increase ' + ((item.qty >= item.max_qty) ? 'disabled' : '') + '">' +
               '<em class="icon iconfont iconproductoptions_ic_qty"></em>' +
               '</span>';
       }

       if (!item.new_free_gift) {
           quantityControlTemplate += '<span class="btn-quantity item_delete"><em class="icon iconfont iconic_delete"></em></span>';
       }

       quantityControlTemplate +=
           '</div>' +
           '</div>';
       var imgTemplate = '<img alt width="90" height="90" src="'+(item.img || litb.resourceURL+'base-images/300x300.png')+'">';

       attrs = '<div class="attr-price"><p class="pr-attr">';
       if(item.display_skus){
        attrs += '<span>' + item.display_skus + '</span>';
       }else if(item.attributes) {
           for (attrName in item.attributes) {
               attrs += '<span><em>' + attrName + ':</em> ' + item.attributes[attrName] + '</span>';
           }
       }
       attrs += '</p><span class="item-price">'+litb.currSymbol + item.price+'</span></div>';
       var template =
           '<dl class="clearfix '+(item.attachment ? 'attachment' :'')+'">' +
           '<dt><a title="'+item.title+'"  href="'+item.href+'">' +
           imgTemplate +
           '</a></dt>' +
           '<dd><h4><a title="'+item.title+'" href="'+item.href+'">'+item.name+'</a></h4>' +
           attrs + quantityControlTemplate +'</dd></dl>';
       return template;
   }
   $('.nav-c-w-l').hover(function(){
        if(litb.mainPage == 'design_product' || litb.mainPage == 'customprint' || litb.mainPage == 'customprint_jubu'){
            return false;
        }
       var $me = $(this),
           arrow_dom = '<div class="top"></div><div class="top-bg"></div>',
           gwURLHead = litb.gwBaseURL;
       if (gwURLHead && !gwURLHead.endsWith('/')) {
           gwURLHead += '/';
       }
       // 兼容aoq加购成功了之后刷新mini购物车的
       var _preTime=$me.data('time');//15s内不刷新
       var now=new Date().getTime();

       if (!$me.data('cartInfo')||!_preTime||(_preTime&&now-_preTime>15000)) {
           $me.data('cartInfo', 'loading');
           $me.data('time',now);
           $("#navCartInfoNote").addClass('loading').html(arrow_dom+litb.langs.loading).show();
           $.getJSON(
               gwURLHead + (litb.lan === 'en' ? '' : litb.lan + '/') + 'index.php?main_page=info_check&action=ajax_shippingcart&callback=?&language='+litb.lan,
               function(data) {
                   if (!data.items || data.items.length == 0) {
                       $('#navCartInfoNote').removeClass('loading').html(arrow_dom+('<p class="cart-empty-icon '+(litb.website == 'lightinthebox' ? 'litb' : (litb.website == 'ouku' ? 'ouku' : ''))+'"></p>')+litb.langs.emptyNavCart);
                       $me.data('cartInfo', 'empty');
                       $(window).trigger("cartNumberChange",0);
                   } else {
                       var items = data.items,
                           prdListHtml = '',
                           maxShow = 10000, totalCount = 0, moreCount = 0;
                       var status = data.success;
                       for (var i = 0; i < items.length; i++) {
                           totalCount += items[i].qty;
                           if (!items[i].attachment) --maxShow;
                           if (maxShow < 0) {
                               moreCount += items[i].qty;
                           } else {
                               prdListHtml += stringifyItem(items[i], i==0);
                           };
                       };
                       //转换0为字符
                       data.cart_mini_num += '';
                       if (data.cart_mini_num!='') {
                           totalCount = data.cart_mini_num;
                       }
                        $(window).trigger("cartNumberChange",totalCount);
                       // header优化
                       $('#navCartProductList').html(prdListHtml);
                       var prodDls = $('#navCartProductList').children('dl');
                       prodDls.each(function(){
                           var $this = $(this),
                               minQty = Number($this.find('.quantity-select').attr('data-min-quantity')),
                               currentQty = $this.find('.quantity-num').attr('value'),
                               decreaseIcon = $this.find('dd .order-quantity .quantity-select .num_decrease');
                           if(minQty == currentQty){
                               decreaseIcon.addClass('disabled');
                           }
                       });

                       $('#navCartProductList a').each(function(){
                           $(this).attr('href',$(this).attr('href')+'?prm='+litb.prm['site']+'.'+litb.prm['page']+'.180.0');
                       });
                       var currency = litb.currency == 'CHF' ? litb.currency : litb.currSymbol;
                       $('#navCartTotal').text(currency + data.addon.cartTotal);

                       $('#navCartMoreItems').show().text(data.miniCartTitle);

                       if ($('#navCartInfoNote').is(':visible')) {
                           $('#navCartInfoNote').hide();
                           $('#navCQE').show();
                       }
                       $me.data('cartInfo', 'haveItems');
                       // header优化
                       if(status){
                           OrderQuantityObj.init();
                       }
                       // 加载商品下拉列表的时候，图片资源错误，展示默认图
                        $("#navCartProductList dt img").each(function(o,img){
                            if(img.src){
                                img = $(img);
                                var oImg = new Image();
                                oImg.onerror = function(){
                                    oImg.onerror = null;
                                    var base = litb.resourceURL || litb.resouceURL; //old is `resouceURL`!
                                    if(Math.round(img.width()/img.height()) === 1){
                                        img.attr("src", base + '/base-images/300x300.png');
                                    }else{
                                        img.attr("src", base + '/base-images/185x300.png');
                                    }
                                };
                                oImg.src = img.attr('src');
                            }
                        });
                   };
               }
           ).fail(function(){
            $('#navCartInfoNote').html(arrow_dom+litb.langs.networkErrorRetry).children('.retry').click(function() {
                $me.data('cartInfo', null);
                $me.trigger('mouseover');
                   });
           });
       } else { // Has been loading or loaded
           switch ($me.data('cartInfo')) {
               case 'loading':
               case 'empty':
                   $('#navCartInfoNote').show();
                   break;
               case 'haveItems':
                   $('#navCQE').show();
           }
       }
   }, function(){
       $(this).children('dd').hide();
   });

   // 加购使用方法
   window.aoqAddToCart = function() {
	   var gwURLHead = litb.gwBaseURL;
       if (gwURLHead && !gwURLHead.endsWith('/')) {
           gwURLHead += '/';
       }
		$.getJSON(
			gwURLHead + (litb.lan === 'en' ? '' : litb.lan + '/') + 'index.php?main_page=info_check&action=ajax_shippingcart&callback=?&language='+litb.lan,
			function(data) {
				if (data.items && data.items.length > 0) {
					var items = data.items,
						prdListHtml = '',
						maxShow = 10000,
						totalCount = 0;
					var status = data.success;
					for (var i = 0; i < items.length; i++) {
						if (!items[i].attachment) --maxShow;
						if (maxShow >= 0) {
							prdListHtml += stringifyItem(items[i]);
						};
					};
					//转换0为字符
					data.cart_mini_num += '';
					if (data.cart_mini_num!='') {
						totalCount = data.cart_mini_num;
					}
                    $(window).trigger("cartNumberChange",totalCount);
					// header优化
					$('#navCartProductList').empty();
					$('#navCartProductList').html(prdListHtml);

					var prodDls = $('#navCartProductList').children('dl');
					prodDls.each(function(){
						var $this = $(this),
							minQty = Number($this.find('.quantity-select').attr('data-min-quantity')),
							currentQty = $this.find('.quantity-num').attr('value'),
							decreaseIcon = $this.find('dd .order-quantity .quantity-select .num_decrease');
						if(minQty == currentQty){
							decreaseIcon.addClass('disabled');
						}
					});

					$('#navCartProductList a').each(function(){
						$(this).attr('href',$(this).attr('href')+'?prm='+litb.prm['site']+'.'+litb.prm['page']+'.180.0');
					});
					$('#navCartTotal').text(litb.currSymbol + data.addon.cartTotal);

					$('#navCartMoreItems').show().text(data.miniCartTitle);

					if ($('#navCartInfoNote').is(':visible')) {
						$('#navCartInfoNote').hide();
						$('#navCQE').show();
					}
					$('.nav-c-w-l').data('cartInfo', 'haveItems');
					// header优化
					if(status){
						OrderQuantityObj.init();
					}
				};
			}
		);
   }
   window.aoqAddToCart();

